auth.probe_js:
// Two independent signals, BOTH observed signed-out on substack.com on 2026-09-12:
//  (1) the page's own state object — window._preloads.userSettings.user_id is null when signed out
//      and set to the account id when signed in (the key exists either way);
//  (2) GET /api/v1/subscriptions — HTTP 401 with {"errors":[{"msg":"Please sign in", ...}]} when
//      signed out, the caller's own subscriptions when signed in.
// The session cookies (connect.sid / substack.sid) are HttpOnly, so document.cookie cannot be the
// gate. NOTE: a 200 alone is not the verdict either — the identifying field is.
let uid = null;
try {
  let p = window._preloads;
  if (typeof p === 'string') p = JSON.parse(p);
  const us = p && p.userSettings;
  if (us && us.user_id) uid = us.user_id;
} catch (e) { uid = null; }
try {
  const r = await fetch('/api/v1/subscriptions', {credentials:'include', headers:{accept:'application/json'}});
  if (r.status === 401 || r.status === 403) return {signed_in:false, why:'subscriptions ' + r.status + ' (please sign in)'};
  let j = null;
  try { j = await r.json(); } catch (e) { j = null; }
  const subs = (j && Array.isArray(j.subscriptions)) ? j.subscriptions : [];
  const u = (j && (j.user || j.currentUser)) || (subs[0] && subs[0].user) || null;
  if (u && (u.handle || u.name || u.id)) return {signed_in:true, as: u.handle || u.name || ('substackid:' + u.id)};
  if (uid) return {signed_in:true, as:'substackid:' + uid, why:'subscriptions ' + r.status + ' carried no user object; _preloads.userSettings.user_id is set'};
  return {signed_in:false, why:'subscriptions ' + r.status + ' but no user field in the body and _preloads.userSettings.user_id is null'};
} catch (e) {
  if (uid) return {signed_in:true, as:'substackid:' + uid, why:'subscriptions fetch failed (' + e.message + '); falling back to _preloads.userSettings.user_id'};
  return {signed_in:false, why:'subscriptions fetch failed and _preloads.userSettings.user_id is null: ' + e.message};
}
